import { HTMLProps } from 'react';
import type * as Stitches from '@stitches/react';
import { config } from '@hexa-ui/theme';

type CSSParagraphVariants = Stitches.CSS<typeof config>;

export interface ParagraphProps extends Omit<HTMLProps<HTMLParagraphElement>, 'size'> {
  size?: 'basis' | 'small' | 'xsmall';
  foreground?: 'true' | 'false';
  colortype?: 'primary' | 'secondary' | 'disabled' | 'success' | 'error';
  alignment?: 'left' | 'center' | 'right';
  weight?: 'normal' | 'medium' | 'semibold';
  selectable?: 'true' | 'false';
  css?: CSSParagraphVariants;
}
